package com.jamshed.hrms.controller;
import com.jamshed.hrms.dto.LeaveRequestDto; import com.jamshed.hrms.entity.*; import com.jamshed.hrms.exception.*; import com.jamshed.hrms.repository.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/leaves") public class LeaveController {private final LeaveRequestRepository r;private final EmployeeRepository er;public LeaveController(LeaveRequestRepository r,EmployeeRepository er){this.r=r;this.er=er;}@GetMapping public List<LeaveRequest> all(){return r.findAll();}@PostMapping public LeaveRequest create(@Valid @RequestBody LeaveRequestDto d){if(d.endDate().isBefore(d.startDate()))throw new BusinessException("End date cannot be before start date");Employee e=er.findById(d.employeeId()).orElseThrow(()->new ResourceNotFoundException("Employee not found"));return r.save(LeaveRequest.builder().employee(e).leaveType(d.leaveType()).startDate(d.startDate()).endDate(d.endDate()).reason(d.reason()).status("PENDING").createdAt(LocalDateTime.now()).build());}@PatchMapping("/{id}/status") public LeaveRequest status(@PathVariable Long id,@RequestParam String value,@RequestParam(required=false) String comment){LeaveRequest x=r.findById(id).orElseThrow(()->new ResourceNotFoundException("Leave request not found"));if(!List.of("APPROVED","REJECTED","CANCELLED").contains(value))throw new BusinessException("Unsupported leave status");x.setStatus(value);x.setManagerComment(comment);return r.save(x);} }
